using System;using System.IO;using System.IO.Pipes;using System.Security.AccessControl;using System.Security.Principal;
class PipeAclCheck {static int Main(string[] args){try{if(args.Length!=1||!args[0].StartsWith("CodexTelegramBridge-"))return 2;using(var p=new NamedPipeClientStream(".",args[0],PipeAccessRights.ReadWrite|PipeAccessRights.ReadPermissions,PipeOptions.None,TokenImpersonationLevel.Identification,HandleInheritability.None)){p.Connect(3000);var security=p.GetAccessControl();var current=WindowsIdentity.GetCurrent().User;bool exact=security.AreAccessRulesProtected&&security.GetOwner(typeof(SecurityIdentifier)).Equals(current);foreach(PipeAccessRule rule in security.GetAccessRules(true,true,typeof(SecurityIdentifier)))if(rule.AccessControlType!=AccessControlType.Allow||!rule.IdentityReference.Equals(current)||rule.IsInherited)exact=false;Console.Write(exact?"OWNER_ONLY":"NOT_OWNER_ONLY");return exact?0:1;}}catch{return 1;}}}
